\begin{tikzpicture}
\begin{axis}[
    width=0.78\textwidth,
    height=0.48\textwidth,
    xmin=0.5, xmax=3.35,
    ymin=0, ymax=11,
    axis lines=left,
    xlabel={\(t\)},
    ylabel={\(s(t)\)},
    xtick={1,2,3},
    ytick={0,4,9},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=0.6:3.25, samples=100] {x^2};
\addplot[thick, domain=1.25:3.25, samples=2] {5*x-6};
\addplot[thick, dashed, domain=1.25:3.1, samples=2] {4.5*x-5};
\addplot[thick, dotted, domain=1.25:3.0, samples=2] {4.2*x-4.4};
\addplot[very thick, domain=1.25:2.9, samples=2] {4*x-4};
\addplot[only marks, mark=*] coordinates {(2,4)};
\node[fill=white, inner sep=1.5pt, anchor=south] at (axis cs:2.0,4.28) {\((2,4)\)};
\node[fill=white, inner sep=1.5pt, anchor=north west] at (axis cs:2.18,4.0) {limiting tangent};
\node[fill=white, inner sep=1.5pt, anchor=east] at (axis cs:1.70,1.0) {secant lines};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.65\textwidth,
    height=0.45\textwidth,
    xmin=-0.3, xmax=2.2,
    ymin=-2, ymax=6,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={1},
    ytick={-1,3},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-0.2:2.1, samples=2] {2*x+1};
\addplot[only marks, mark=o, mark size=3pt, thick] coordinates {(1,3)};
\addplot[only marks, mark=*, mark size=2.5pt] coordinates {(1,-1)};
\node[anchor=west] at (axis cs:1.0,2.8) {hole at the limiting value};
\node[anchor=west] at (axis cs:1.08,-0.8) {actual value \(F(1)\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.65\textwidth,
    height=0.42\textwidth,
    xmin=-2, xmax=2,
    ymin=-1.6, ymax=1.6,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(J(x)\)},
    xtick={-1,0,1},
    ytick={-1,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-2:-0.05, samples=2] {-1};
\addplot[thick, domain=0.05:2, samples=2] {1};
\addplot[only marks, mark=o, mark size=3pt, thick] coordinates {(0,-1) (0,1)};
\node[anchor=south west] at (axis cs:0.18,1.22) {right side approaches \(1\)};
\node[anchor=north east] at (axis cs:-0.18,-1.22) {left side approaches \(-1\)};
\end{axis}
\end{tikzpicture}
